local rows = text.values
rows["100:1392962730"]="크레딧의 메인:\010퀘스트 스크립터:\010\013==============================\010\013슐츠, 테슬리비, 나머지 RPG 팀\010\013\010"
rows["101:270244065"]="\"(1) 주정뱅이 라리크: 오우거. 결코 술집을 떠나지 않음. 야비함. 못 생겼음. 뚱뚱함. 천박함. 또한 매우 뚱뚱함.\013\010\013\010[다음 페이지]\""
rows["102:2007232664"]="\"내게 실예의 별, 다군의 손, 그리고 고대의 심장, 이 세 가지를 가져오십시오. 그러면 야그인의 법전을 주겠습니다.\013\010\013\010- 게릭 본그립\""
rows["103:1332187580"]="당신은 이 장부에 적힌 단어를 하나도 이해할 수 없군요. 무슨 언어로 쓰여 있는지조차 모르잖아요!"
rows["103:9238170"]="잘 들어, 버드!\010\010네가 빚진 돈을 몽땅 갚기 전까진 이게 내가 보내는 마지막 얼간이다.\010\010더는 질질 끌지 마!\010\010그리프타"
rows["105:1269015148"]="<글씨는 알아볼 수 없는 닭발 같은 낙서지만, 분홍색에 대한 언급 몇 군데는 겨우 읽을 수 있다...>"
rows["105:1602685672"]="이 물건들을 찾아서 가젯잔으로 돌아가서, 이 책과 함께 보답을 드리겠습니다. "
rows["105:75728081"]="이 설명서의 페이지를 채우는 소용돌이 치는 기호와 그림은 이해할 수 없을 정도로 난해합니다."
rows["107:1485269082"]="<불타는 깃발은 신자들에게 선물로 제공되었는데, 오직 두 단어만 읽을 수 있습니다."
rows["107:359917020"]="섬의 범위를 정찰하고 돌아와 보고하라.$B$B명심해라. 절대로 들키지 마라!$B$B나를 실망시키지 마라, 캔드레스!$B$BS."
rows["111:1870696927"]="\"야나 블러드스피어\013\010붉은십자군의 암살부단장\013\010달라란 시민\013\010티리스팔 숲에서 실종됨\""
rows["111:1990011502"]="<지상에 흩어져 있는 상자, 덮개에 새겨져 있는 것:"
rows["111:22780115"]="<HTML>\010<BODY>\010<H1 align=\"center\">\010앤서니 레이 스타크\010</H1>\010<H2 align=\"center\">\0101961 - 2005\010</H2>\010</BODY>\010</HTML>"
rows["113:2138022817"]="펠라리 스위프트애로우\010\013붉은십자군의 순찰대장\010\013쿠엘탈라스 시민\010\013은빛소나무 숲에서 실종됨"
rows["115:1017159001"]="여기 브랜든 알스토르는$B$B사랑받는 전도자, 헌신적인 치료자, 진정한 친구$B$B당신의 영혼이 영원한 평화를 찾을 수 있기를 바랍니다."
rows["115:1493250317"]="뇌에에에.... 뇌에에에에에에에. 뇌에에에에에에에에!$B$B<이런 것만 40장을 넘게 적혀 있습니다.> "
rows["115:872528927"]="이상을 높게 받들고 적을 짓밟아라! 무너진 적을 우리 안에 받아들여라. 세상 모두가 얼어붙은 왕좌 앞에 무릎 꿇을 때까지!"
rows["116:1799963374"]="\"내게 실예의 별, 다군의 손, 그리고 고대의 심장, 이 세 가지를 가져오시오. 그러면 야그인의 법전을 주겠소.\013\010\013\010- 관리인 벨두거\""
rows["117:209483380"]="이 쪽지의 글자는 표면 전체에서 깜박이고 춤추는 것처럼 보입니다. 그들에게서 의미를 수집하는 것은 불가능합니다 ..."
rows["117:444789680"]="외팔이 인바르\010붉은십자군의 암살단장\010달라란 시민\010노스렌드 해안에서 마지막으로 목격됨"
rows["117:632288650"]="내일 특별한 누군가를 만나게 될 것이다. 기억해라. 몽둥이로 때려죽이는 것보다 친절하게 대하는 편이 친구를 더 많이 만든다."
rows["118:1256264413"]="제독 바리안 웨스트윈드\010붉은십자군 함대의 총사령관\010쿨티라스 시민\010노스렌드의 얼어붙은 해안에서 실종됨"
rows["119:1425351713"]="친구나 친척, 지인, 길 가는 낯선 사람, 심지어 네 양심이 뭐라고 하든 너는 특별한 존재다."
rows["120:1746763780"]="이름: 코발\010상태: 사망\010비고: 사망하였음. 그리 높은 지위는 아니었음. 아마도 고통스러웠던 일생에서 벗어난 것으로 사료됨.\010"
rows["120:941278851"]="\"일을 끝낸 마지막 날 해질 무렵, 티탄들은 이 대륙에 `영원한 별빛의 땅`이란 뜻의 칼림도어라는 이름을 지어 주었다.\""
rows["121:1129686954"]="파멸을 불러오는 아르토리우스:$B$B아르토리우스는 윈터스프링에서 그가 닿는 모든 것에 타락과 파멸을 불러온다. 그를 찾아내어 처치하라."
rows["121:878659796"]="미치광이 클린프란:$B$B클린프란은 불타는 초원을 배회합니다. 조심스럽게 접근하여 그의 본모습을 드러내도록 하십시오."
rows["122:465692802"]="주의: 여러 개의 라바 폭발을 연속적으로 마시는 것은 자발적인 연료를 초래할 수 있습니다.$B새 LAVA Blast이 들어왔어요!"
rows["123:1010682872"]="이 사전의 뒤이은 497쪽은 전부 슈퍼 스냅퍼 FX 2000으로 기묘한 각도에서 찍은 사진들로만 이루어져 있다."
rows["123:932940551"]="마티아스 쇼가 심부름꾼을 보내 날 죽이려고 했어.\010\010지금 그 <illegible text>녀석이 밖에서 순찰을 돌고 있어. 생각 없고 생명력 없는 꼭두각시 같으니.\010\010하하하!"
rows["124:1257300661"]="야간 당직, 2번째 종$B세드릭이 돛대에 올라가서 비틀거리다가 떨어졌다. 선의에게 치료를 받았다. 술 좀 깨라고 아래쪽에 배치됐다."
rows["124:189006416"]="이름: 멜트$B상태: 생존*$B비고: 구울로 변함. 붉은십자군 농부에게 살해됨. 먼치가 구울 하수인으로 되살림."
rows["125:1693959395"]="오래전 북풍만이 이 봉우리들을 지배하던 시절, 강력한 타운카 족장의 형제가 이 땅을 탐냈다."
rows["126:102789860"]="이 젊은 마법사들은 동족을 위한 책임보다는 개인의 욕심을 채우기 위해 마법을 사용하기 시작했다."
rows["128:144015625"]="\"스트롬가드의 오르만\013\010붉은십자군의 초대 총지휘관\013\010스트롬가드 시민\013\010얼음왕관 빙하 입구에서 실종됨\""
rows["128:1881877492"]=" ⁇ 에 매달린 글자는:"
rows["128:569370616"]="사령관에게,\010\010암호는 줄루헤드에게 전달하라. 별도의 지시가 있을 때까지 그의 관리 아래 둘 것이다.\010\010- 일리단 스톰레이지 경"
rows["130:1830798216"]="<최근에 부착된 전단지입니다. 돌 위에 남은 접착제의 흔적으로 보아, 이전에는 이곳에 수많은 전단지가 붙어 있었음을 알 수 있습니다.>"
rows["130:2018757491"]="$B$B추신 - 우리의 대마법학자가 아웃랜드에서 스랄의 질문에 대한 답변을 받아 왔습니다.$B$B<이 편지에는 여군주 실바나스 윈드러너의 인장이 추가로 찍혀 있습니다.>"
rows["130:806117088"]="\"아렐라스 파이어리프\013\010붉은십자군의 고위 마법사\013\010쿠엘탈라스 시민\013\010강령술사 디샐븐과의 영원한 전투 속에 갇힘\""
rows["133:991905604"]="\"여덟째 날\013\010우리가 처음에 생각했던 것처럼 트롤들이 큰 문제가 되지 않을지도 모르겠다. 그 수는 상당하지만 무기가 형편 없고 조직적이지도 못하다. 적은 수의 병력으로도 충분히 놈들을 상대할 수 있을 것이다.\""
rows["135:1295112294"]="드디어 총회에서 날 인정했다. 스칼로맨스 입학 허가를 받은 것이다! 오늘부터 언데드의 일원이 되기를 위한 영광스러운 삶이 시작된다!"
rows["135:193484009"]="\"아래에 위대한 사이클로니안을 소환하는 마법 주문에 필요한 것들을 적어 놓았네. 행운이 함께하길 빌겠네.\013\010\013\010- 바람의감시자 바스라\""
rows["136:1108767730"]="사냥꾼이여, 경고하건대, 이 악마들은 그들의 방식대로 싸워야 한다. 만약 그들이 너보다 약하다고 느끼면 도망칠 것이다.$B$B혼자 가라."
rows["137:1792838969"]="베테크 스톰브로$B$B베테크는 정처 없이 헤매다 검은바위 산의 깊은 곳에 이르게 된다. 산의 비밀이 그를 부르고 있다.$B$B그의 영혼이 흔들리지 않기를."
rows["139:605524115"]="이 갑옷 문장을 동부 벌목지에 있는 팀버레인 가족에게 가져가면 가죽이나 헝겊으로 만든 갑옷과 교환할 수 있습니다."
rows["140:1211798659"]="족장의 형제 스톰후프는 온 힘을 모아 폭풍우 봉우리를 정당한 지배자인 북풍에게서 빼앗으려 길을 나섰다."
rows["141:1144693771"]="<HTML>\010<BODY>\010<H1 align=\"center\">\010서쪽 수정탑 도표\010</H1>\010<BR/>\010<IMG src=\"Interface\\Pictures\\11482_crystals_west\"/>\010</BODY>\010</HTML>"
rows["141:1775786158"]="<HTML>\010<BODY>\010<H1 align=\"center\">\010동쪽 수정탑 도표\010</H1>\010<BR/>\010<IMG src=\"Interface\\Pictures\\11482_crystals_east\"/>\010</BODY>\010</HTML>"
rows["141:1873225945"]="곳곳에 위험이 만연해 있고,$B적들은 우리에게 다시 한번 족쇄를 채우려 하니...$B$B전투를 할 때면 기억하라!$B반드시 해야 할 일을 해냈던 영웅을!$B그롬 헬스크림이여, 영원하라!"
rows["141:486352179"]="\"형제들이여, 우리는 한때 자부심 있는 장인이었다는 사실을 기억하기 바란다. 우리는 예전에 우리가 장인이었을 때와 마찬가지로 지금 우리에게 주어진 임무를 정확하게 수행해 낼 것이다.\013\010\013\010-EVC\""
rows["141:502559499"]="포로르의 용 사냥 총서는 글이 빼곡히 적힌 두꺼운 책입니다. 하지만 안타깝게도 글씨가 깨져 보여서 무슨 말인지 전혀 알 수 없습니다."
rows["142:2092269108"]=" 페렌 마커스\013\010\013\010붉은십자군 수도원의 대수도원장 \013\010\013\010스트라솔름 시민\013\010\013\010첫번째 대공습에서 붉은십자군 수도원을 방어하는 도중 전사함"
